(function(){"use strict";const i=window.NPData;if(!i)return;const n=(h,a,r,e,m,c,s)=>({id:h,tier:a,topic:r,when:e,face:m,text:c,once:!!s}),t=[n("s1",0,"story",{},"smile","Rin tới rồi hả? Chị Vân nè, trực bộ đàm của trạm. Có gì cứ gọi chị nha.",!0),n("s1b",0,"story",{runs:3},"warm","Mẹ chị với ngoại em là bạn đưa thư ngày xưa. Nên chị mới kêu em qua đây.",!0),n("s2",0,"story",{runs:8},"warm","Mẹ chị ngày xưa cũng đưa thư, đạp xe quanh bưu điện Sài Gòn. Năm 1962 mẹ mới mười chín tuổi.",!0),n("s3",0,"story",{runs:15},"warm","Mẹ hay kể về một chú tên Tư, sáng nào cũng đóng dấu, chiều nào cũng ngồi ngắm đồng hồ.",!0),n("s4",0,"story",{runs:24},"wow","Hôm nay chị lục được túi thư cũ của mẹ. Trong túi có một con tem in ngược, lạ ghê.",!0),n("s5",0,"story",{runs:34},"warm","Mẹ chị nói: thư tay đi chậm, nhưng tới nơi thì ở lại lâu. Càng ngày chị càng thấy mẹ đúng.",!0),n("s6",0,"story",{runs:45},"sad","Mẹ mà biết bây giờ còn người giữ cái nghề này, chắc mẹ vui lắm. Cảm ơn em nhiều.",!0),n("f_win",1,"first",{ok:!0},"smile","Chuyến đầu về đích! Khách gọi về khen rồi đó. Cứ thế mà chạy.",!0),n("f_fall",1,"first",{ok:!1,cause:"fall"},"worry","Rơi khỏi mái rồi à? Ai mới chạy cũng vậy. Nhìn mép mái trước khi nhảy nha.",!0),n("f_boss",1,"first",{boss:!0},"wow","Hạ được trùm rồi hả? Cả trạm đang vỗ tay qua bộ đàm đây!",!0),n("f_3star",1,"first",{stars3:!0},"wow","Đủ ba sao! Chị ghim tên em lên bảng của trạm rồi.",!0),n("f_late",1,"first",{late:!0,ok:!0},"tease","Ca khuya mà vẫn giao đủ. Em không ngủ hay sao vậy?",!0),n("f_best",1,"first",{best:!0},"smile","Kỷ lục mới! Chị ghi vào sổ trực ca bằng mực đỏ.",!0),n("f_era",1,"first",{era:!0},"wow","Em vừa giao hàng ở một thời đại khác thật à? Bộ đàm của chị rè hết cả.",!0),n("f_meal",1,"first",{meal:!0,ok:!0},"tease","No bụng chạy khoẻ hẳn. Lần sau nhớ mua phần chị một suất.",!0),n("f_kit",1,"first",{kit:!0},"smile","Mang đồ nghề theo là khôn đó. Đường xa có lúc cần.",!0),n("f_quit",1,"first",{cause:"quit"},"worry","Bỏ ngang chuyến à? Không sao, khách sẽ chờ thêm một chút.",!0),n("r_stomp",2,"stomp",{min:{stomps:15}},"wow","Đạp liền mười mấy drone. Bên kỹ thuật hỏi em có thù gì với tụi nó không."),n("r_near",2,"near",{min:{near:8}},"worry","Sượt qua nguy hiểm cả chục lần. Tim chị đập theo em luôn đó."),n("r_zip",2,"zip",{min:{zips:5}},"smile","Đu dây cáp nhiều ghê. Em coi mái nhà như sân chơi rồi."),n("r_slam",2,"slam",{min:{slams:10}},"tease","Dậm mái nhiều quá, cư dân gọi lên hỏi có động đất không."),n("r_dash",2,"dash",{min:{dashes:30}},"tease","Lướt ba chục lần một chuyến. Giày em chắc mòn hết đế rồi."),n("r_crate",2,"crate",{min:{crates:4}},"smile","Nhặt được nhiều thùng tiếp tế quá. Ai đó trên kia thương em ghê."),n("r_rival",2,"rival",{min:{rivals:1}},"wow","Thắng cô bưu tá áo đỏ rồi hả? Lâu lắm mới thấy cô ấy chịu thua."),n("r_lant",2,"lant",{min:{lant:3}},"warm","Đèn trời bay đẹp không? Ở trạm chị chỉ nghe kể thôi."),n("r_gold",2,"gold",{min:{gold:1}},"wow","Kiện vàng! Hôm nay ai đó có quà sang lắm."),n("r_pool",2,"pool",{min:{pools:1}},"tease","Nghe nói em rơi xuống hồ bơi trên mái. Có mang đồ thay không vậy?"),n("m_ice",3,"map",{map:["iceland"],ok:!0},"warm","Iceland lạnh không? Chị để sẵn ly cacao nóng ở trạm cho em."),n("m_sahara",3,"map",{map:["sahara","egypt"],ok:!0},"tease","Cát vô giày chưa? Lúc về nhớ giũ trước khi vào trạm nha."),n("m_venice",3,"map",{map:["venice"],ok:!0},"smile","Venice toàn nước mà em không ướt chiếc kiện nào. Giỏi!"),n("m_sg",3,"map",{map:["saigon"],ok:!0},"warm","Về tới Sài Gòn rồi hả? Ghé thăm ngoại giùm chị."),n("m_saigon",3,"map",{map:["neon"],ok:!0},"warm","Chạy quanh phố nhà vẫn là sướng nhất. Hẻm nào em cũng thuộc rồi."),n("m_rio",3,"map",{map:["rio"],ok:!0},"smile","Rio vui không? Qua bộ đàm chị còn nghe tiếng trống samba."),n("m_fuji",3,"map",{map:["fuji"],ok:!0},"warm","Núi Phú Sĩ đẹp lắm phải không? Chụp giùm chị một tấm nha."),n("m_paris",3,"map",{map:["paris"],ok:!0},"smile","Paris về rồi à? Lần sau mang giùm chị một cái bánh sừng bò."),n("m_halong",3,"map",{map:["halong"],ok:!0},"warm","Vịnh Hạ Long có sương không? Chị nghe nói buổi sáng đẹp nhất."),n("m_era",3,"map",{era:!0,ok:!0},"wow","Lại một chuyến xuyên thời gian. Bà Thời gửi lời khen qua bộ đàm."),n("m_late",3,"late",{late:!0,ok:!0},"tease","Giờ này còn chạy. Nhớ ngủ bù đó, Rin."),n("c_fall",4,"fall",{ok:!1,cause:"fall"},"worry","Lại hụt chân rồi. Nhảy sớm một nhịp là qua thôi."),n("c_fall2",4,"fall",{ok:!1,cause:"fall"},"tease","Mái nhà không có tay vịn đâu nha. Thử lại đi."),n("c_drone",4,"drone",{ok:!1,cause:["drone","gunner"]},"worry","Drone chặn đường à? Đạp từ trên xuống là chúng chịu thua liền."),n("c_drone2",4,"drone",{ok:!1,cause:["drone","gunner"]},"sad","Bị bắn hạ rồi. Giữ khoảng cách, đợi nó báo đòn xong hẵng lao vào."),n("c_boss",4,"boss",{ok:!1,cause:["boss","zap","bomb"]},"worry","Trùm mạnh thật. Nhìn kỹ lúc nó báo đòn, đó là lúc nó hở."),n("c_spike",4,"spike",{ok:!1,cause:"meteor"},"worry","Coi chừng mấy thứ rơi từ trên trời. Nghe tiếng rít là né."),n("c_quit",4,"quit",{cause:"quit"},"warm","Mệt thì nghỉ chút. Trạm vẫn để đèn chờ em."),n("g_win1",5,"win",{ok:!0},"smile","Giao đủ, khách vui, trạm vui. Một ngày đẹp."),n("g_win2",5,"win",{ok:!0},"warm","Chị vừa ghi chuyến của em vào sổ. Nét chữ hôm nay đẹp hơn mọi hôm."),n("g_win3",5,"win",{ok:!0},"tease","Nhanh ghê. Em có chắc là không bay không đó?"),n("g_win4",5,"win",{ok:!0},"smile","Khách gửi lời cảm ơn kèm một cái bánh. Chị ăn giùm rồi nha."),n("g_win5",5,"win",{ok:!0},"warm","Có khách hỏi bưu tá hôm nay tên gì. Chị nói: Rin, nhớ nha."),n("g_win6",5,"win",{ok:!0},"smile","Bảng đơn ở trạm vơi bớt rồi. Cảm ơn em nha."),n("g_win7",5,"win",{ok:!0},"tease","Đi đường cẩn thận, đừng để Bé Kiện ngủ gật trên vai."),n("g_win8",5,"win",{ok:!0},"warm","Mưa nắng gì thì thư vẫn tới. Đó là nghề của mình."),n("g_lose1",5,"lose",{ok:!1},"sad","Không sao đâu. Khách vẫn nhận được hàng, chỉ trễ chút thôi."),n("g_lose2",5,"lose",{ok:!1},"warm","Uống miếng nước rồi chạy lại nha. Chị chờ ở đầu dây."),n("g_lose3",5,"lose",{ok:!1},"worry","Hôm nay trời không thương mình. Mai trời thương."),n("g_lose4",5,"lose",{ok:!1},"tease","Ngã một lần thì khôn một lần. Em sắp thành thiên tài rồi đó."),n("g_lose5",5,"lose",{ok:!1},"warm","Chuyến hỏng nhưng em còn nguyên vẹn. Vậy là được rồi."),n("g_lose6",5,"lose",{ok:!1,runs:8},"sad","Mẹ chị hay nói: thư nào rồi cũng tới tay người nhận.")];i.GROW_DISPATCH={lines:t,tipAt:3,tip:"Trùm {title} lại cản em à? Mẹo nè: {sub}.",tipShort:"Mẹo trùm {title}: {sub}.",who:"Chị Vân",cool:4}})();
