(function(){"use strict";const n=window.NPData;n&&(n.GROW_MEM={title:"SỔ TEM CỦA NGOẠI",sub:"Mỗi ký ức là một con tem nhà.",list:[{id:"to",name:"Tô đầu tiên",runs:1,play:!0,lines:["Hồi tám tuổi, Rin bưng tô hủ tiếu đầu tiên cho xe cô Sáu.","Tô đầy đi hành lang. Tô không về đường mái tôn."]},{id:"tem",name:"Sổ tem của ngoại",runs:2,lines:["Chỗ này có thiệt hông ngoại?","Có. Tại chưa ai tới giao thôi."]},{id:"tuyen",name:"Đi tuyến với ngoại",runs:4,play:!0,lines:["Rin ngồi yên sau xe đạp, thuộc từng số nhà.","Ba má con đi làm xa. Thư tới là ba má tới."]},{id:"kien",name:"Kiện trên nóc tủ",runs:6,lines:["Rin lắc thử cái kiện trên nóc tủ. Nó lắc lại.","Địa chỉ này chưa có trên bản đồ, ngoại nói."]},{id:"ve",name:"Về thăm ngoại",runs:1,map:"saigon",lines:["Ngoại đứng chờ ngoài ban công, tay cầm sổ tem.","Con tới đâu, ngoại dán tem tới đó."]},{id:"nhan",name:"Người nhận",runs:1,after:5,lines:["Nhãn trên Bé Kiện sáng lên dòng cuối: Người nhận: Phong.","Kiện hàng ngoại chưa giao được, hoá ra là gửi cho con."]}]})})();
